    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m, k;
    cin >> n >> m >> k;

    vector<long long> a(n);
    for (auto& x : a) cin >> x;

    sort(a.rbegin(), a.rend());

    long long total = k;
    for (long long x : a) total += x - 1;

    if (m > total) {
        cout << -1;
        return 0;
    }

    int used = 0;
    while (m > k) {
        m -= a[used] - 1;
        ++used;
    }

    cout << used;
    return 0;
}

